/// One stack frame: the context plus captures for dynamic rules pushed with it.
#[derive(Clone, PartialEq, Eq, Hash, Debug)]
pub struct Frame { pub context: ContextId, pub captures: Option<std::sync::Arc<[String]>> }

/// The per-line-end highlighting state: the context stack. Interned because most lines share a few states.
#[derive(Clone, PartialEq, Eq, Hash, Debug)]
pub struct State { frames: smallvec::SmallVec<[Frame; 8]> }

#[derive(Copy, Clone, PartialEq, Eq, Hash, Debug)]
pub struct StateId(pub u32);

pub struct StateInterner { states: Vec<State>, ids: std::collections::HashMap<State, StateId> }
impl StateInterner {
    pub fn new(initial: ContextId) -> Self; // StateId(0) is the initial state
    pub fn intern(&mut self, s: State) -> StateId;
    pub fn get(&self, id: StateId) -> &State;
    pub fn initial(&self) -> StateId;
}

#[derive(Copy, Clone, PartialEq, Eq, Debug)]
pub struct Span { pub start: u32, pub len: u32, pub format: FormatId } // char columns

#[derive(Copy, Clone, PartialEq, Eq, Debug)]
pub enum FoldEvent { Begin { col: u32, region: FoldId }, End { col: u32, region: FoldId } }

#[derive(Clone, Default, PartialEq, Eq, Debug)]
pub struct LineHighlight { pub spans: Vec<Span>, pub folds: Vec<FoldEvent>, pub end_state: StateId }

pub struct Highlighter<'a> { repo: &'a Repository, regexes: RegexCache, interner: StateInterner }
impl<'a> Highlighter<'a> {
    pub fn new(repo: &'a Repository, def: DefId) -> Result<Self, RegexError>;
    pub fn initial_state(&self) -> StateId;
    /// Deterministic: same (line, start) always yields the same output. Reuses `out` allocations.
    pub fn highlight_line(&mut self, line: &str, start: StateId, out: &mut LineHighlight);
    pub fn interner(&self) -> &StateInterner;
}

/// PCRE-flavoured patterns from the XML, compiled once. `fancy-regex` handles lookaround and
/// backreferences; patterns it cannot compile are reported at load, not at match time.
pub struct RegexCache { by_rule: std::collections::HashMap<(ContextId, u16), fancy_regex::Regex>, dynamic: lru::LruCache<String, fancy_regex::Regex> }

/// Translates QRegularExpression syntax that differs from fancy-regex (POSIX classes, \h, \R, (?i) placement) and
/// expands `%1`..`%9` from captures for dynamic rules.
pub fn translate_pattern(pcre: &str, insensitive: bool, minimal: bool, captures: Option<&[String]>) -> Result<String, RegexError>;

#[derive(Debug)]
pub enum RegexError { Unsupported { pattern: String, reason: String } }
